CREATE TABLE work_schedules (id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,department_id VARCHAR(36) NOT NULL,employee_code VARCHAR(32) NOT NULL,employee_name VARCHAR(120) NOT NULL,day VARCHAR(10) NOT NULL,start VARCHAR(32) NOT NULL,end VARCHAR(32) NOT NULL,overnight INT NOT NULL DEFAULT 0,break_minutes INT NOT NULL DEFAULT 0,note TEXT NOT NULL,version INT NOT NULL DEFAULT 1,deleted INT NOT NULL DEFAULT 0,created_at VARCHAR(32) NOT NULL,updated_at VARCHAR(32) NOT NULL,FOREIGN KEY (user_id) REFERENCES users(id),INDEX work_schedule_user_day(user_id,day),INDEX work_schedule_department_day(department_id,day));
